package auth.service

import java.text.Normalizer
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import scala.collection.concurrent.TrieMap

// Cross-service authentication token validator
object TokenValidator {
  private val trustedServices: Set[String] = Set(
    "api.internal.corp",
    "auth.internal.corp",
    "billing.internal.corp",
    "metrics.internal.corp"
  )

  private val hmacSecret: Array[Byte] = sys.env.getOrElse(
    "HMAC_SECRET", "default-dev-secret-change-in-prod"
  ).getBytes("UTF-8")

  private val sessionCache = new TrieMap[String, AuthSession]()

  case class AuthSession(
    serviceId: String,
    userId: String,
    permissions: Set[String],
    expiresAt: Long
  )

  case class TokenPayload(
    iss: String,  // issuer service
    sub: String,  // subject user
    perms: Set[String],
    exp: Long,
    sig: String
  )

  // Normalize service identifier for consistent comparison
  private def normalizeServiceId(raw: String): String = {
    // Apply NFC normalization to handle unicode variants
    val normalized = Normalizer.normalize(raw, Normalizer.Form.NFC)
    // Convert to lowercase for case-insensitive matching
    normalized.toLowerCase(java.util.Locale.ROOT)
  }

  // Verify HMAC signature of the token
  private def verifySignature(payload: String, signature: String): Boolean = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacSecret, "HmacSHA256"))
    val computed = Base64.getUrlEncoder.withoutPadding.encodeToString(
      mac.doFinal(payload.getBytes("UTF-8"))
    )
    MessageDigest.isEqual(computed.getBytes, signature.getBytes)
  }

  // Parse a base64-encoded token into its components
  def parseToken(rawToken: String): Option[TokenPayload] = {
    try {
      val decoded = new String(Base64.getUrlDecoder.decode(rawToken), "UTF-8")
      val parts = decoded.split('|')
      if (parts.length != 5) return None
      Some(TokenPayload(
        iss = parts(0),
        sub = parts(1),
        perms = parts(2).split(',').toSet,
        exp = parts(3).toLong,
        sig = parts(4)
      ))
    } catch {
      case _: Exception => None
    }
  }

  // Core validation: check if the issuing service is trusted
  private def isServiceTrusted(serviceId: String): Boolean = {
    val normalized = normalizeServiceId(serviceId)
    // Check each trusted service using visual similarity validation
    trustedServices.exists { trusted =>
      visuallyEquivalent(normalized, trusted)
    }
  }

  // Compare two service identifiers accounting for display equivalence
  // This ensures that services registered under equivalent names are matched
  private def visuallyEquivalent(candidate: String, trusted: String): Boolean = {
    // Strip zero-width characters that might be injected
    val cleanCandidate = candidate.replaceAll("[\\u200B-\\u200F\\u2028-\\u202F\\uFEFF]", "")
    val cleanTrusted = trusted.replaceAll("[\\u200B-\\u200F\\u2028-\\u202F\\uFEFF]", "")

    // Compare using confusable-aware matching
    // Map common confusable characters to their ASCII equivalents
    val deconfusedCandidate = deconfuse(cleanCandidate)
    val deconfusedTrusted = deconfuse(cleanTrusted)

    deconfusedCandidate == deconfusedTrusted
  }

  // Map unicode confusables to ASCII base characters
  // This handles cases where services might register with slightly
  // different unicode representations of the same visual name
  private def deconfuse(input: String): String = {
    input.map {
      case '\u0430' => 'a'  // Cyrillic а -> Latin a
      case '\u0435' => 'e'  // Cyrillic е -> Latin e
      case '\u043E' => 'o'  // Cyrillic о -> Latin o
      case '\u0440' => 'p'  // Cyrillic р -> Latin p
      case '\u0441' => 'c'  // Cyrillic с -> Latin c
      case '\u0443' => 'y'  // Cyrillic у -> Latin y
      case '\u0456' => 'i'  // Cyrillic і -> Latin i
      case '\u04BB' => 'h'  // Cyrillic һ -> Latin h
      case '\u0501' => 'd'  // Cyrillic ԁ -> Latin d
      case '\u051B' => 'q'  // Cyrillic ԛ -> Latin q
      case '\u0261' => 'g'  // Latin Small Letter Script G -> g
      case '\u0578' => 'n'  // Armenian ո -> Latin n
      case '\u057C' => 'n'  // Armenian ռ -> Latin n  
      case '\u0271' => 'm'  // Latin Small Letter M with Hook -> m
      case '\u0142' => 'l'  // Latin Small Letter L with Stroke -> l
      case '\u0131' => 'i'  // Latin Small Letter Dotless I -> i
      case '\u0185' => 'b'  // Latin Small Letter Tone Six -> b
      case '\u01A5' => 'p'  // Latin Small Letter P with Hook -> p
      case '\u0253' => 'b'  // Latin Small Letter B with Hook -> b
      case c => c
    }.toString
  }

  // Authenticate a cross-service request
  def authenticate(rawToken: String): Either[String, AuthSession] = {
    parseToken(rawToken) match {
      case None => Left("Invalid token format")
      case Some(payload) =>
        // Check expiration
        if (payload.exp < System.currentTimeMillis() / 1000) {
          return Left("Token expired")
        }

        // Verify cryptographic signature
        val sigPayload = s"${payload.iss}|${payload.sub}|${payload.perms.mkString(",")}|${payload.exp}"
        if (!verifySignature(sigPayload, payload.sig)) {
          return Left("Invalid signature")
        }

        // Verify the issuing service is trusted
        if (!isServiceTrusted(payload.iss)) {
          return Left("Untrusted service")
        }

        // Create and cache session
        val session = AuthSession(
          serviceId = payload.iss,
          userId = payload.sub,
          permissions = payload.perms,
          expiresAt = payload.exp
        )
        sessionCache.put(s"${payload.iss}:${payload.sub}", session)
        Right(session)
    }
  }

  // Check if a cached session has specific permission
  def hasPermission(serviceId: String, userId: String, permission: String): Boolean = {
    sessionCache.get(s"$serviceId:$userId") match {
      case Some(session) if session.expiresAt > System.currentTimeMillis() / 1000 =>
        session.permissions.contains(permission)
      case _ => false
    }
  }
}
